#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *a = (long long *)malloc((N + 1) * sizeof(long long));
    long long *sum = (long long *)calloc(N + 1, sizeof(long long));
    if (!a || !sum) return 0;

    for (int i = 1; i <= N; i++) scanf("%lld", &a[i]);

    /* 
       If we choose some x, all multiples of x are broken.
       Therefore the set of remaining gems S must satisfy:
       if i remains and d divides i, then d also remains.
       So S is a divisor-closed set.

       Let keep[i] indicate whether gem i remains.
       For each i, if i remains, then all divisors of i remain.

       Define dp[i] = maximum total reward obtainable from gems whose labels divide i,
       under the condition that i remains.
       Then:
         dp[i] = a[i] + sum_{d proper divisor of i} max(0, contribution of subtree rooted at d not already counted)
       A simpler equivalent recurrence is:
         sum[i] = total optimal contribution of all kept gems in the divisor-lattice subtree ending at i
       computed by divisor DP:
         sum[i] starts as a[i], and for each multiple j = 2i,3i,... we add positive benefit from keeping j
         only when i is kept.

       Processing downward:
         best[i] = a[i] + sum over k>=2 of max(0, best[k*i])
       Answer = max(0, best[1])? No, because 1 is always a divisor of every kept gem, so any non-empty kept set must include 1.
       But empty set is also allowed by smashing x=1.
       Thus answer = max(0, best[1]).
    */

    for (int i = N; i >= 1; i--) {
        long long cur = a[i];
        for (int j = i + i; j <= N; j += i) {
            if (sum[j] > 0) cur += sum[j];
        }
        sum[i] = cur;
    }

    long long ans = sum[1];
    if (ans < 0) ans = 0;
    printf("%lld\n", ans);

    free(a);
    free(sum);
    return 0;
}

