int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N + 1);
    for (int i = 1; i <= N; i++) cin >> a[i];

    // If we choose some x, all multiples of x are broken.
    // Therefore, the set of remaining gems must be "divisor-closed":
    // if i remains, then every divisor of i must also remain.
    //
    // Let dp[i] = maximum total reward obtainable considering only gems
    // whose labels divide i, under the condition that i remains.
    //
    // Then:
    // dp[i] = a[i] + sum over children in divisor-lattice of max(0, contribution)
    //
    // A convenient way:
    // Start with dp[i] = a[i].
    // For i from large to small, add positive dp[j] of multiples j = 2i, 3i, ...
    // to dp[i]. This works because if i remains, for each immediate-or-not multiple j,
    // the optimal divisor-closed subset rooted at j can be included independently
    // only when beneficial.
    //
    // Finally, answer is max(0, dp[1])? Actually gem 1 may also be broken by choosing x=1.
    // Choosing x=1 breaks everything, giving 0. So answer is max(0, best subset containing 1).
    //
    // The recurrence below computes best total among divisor-closed subsets with minimum element i.
    // Standard DP:
    // dp[i] = a[i] + sum_{k>=2} max(0, dp[i*k])
    // answer = max(0, dp[1])

    vector<long long> dp = a;

    for (int i = N; i >= 1; i--) {
        for (int j = i + i; j <= N; j += i) {
            if (dp[j] > 0) dp[i] += dp[j];
        }
    }

    cout << max(0LL, dp[1]) << '\n';
    return 0;
